        unsigned tag);

static inline clist_node_t *clist_lpop(clist_node_t *list) /* <=== clist_lpop */ 
{
    if (list->next) {
        clist_node_t *first = list->next->next;
        if (list->next == first) {
            list->next = NULL;
        }
        else {
            list->next->next = first->next;
        }
        return first;
    }
    else {
        return NULL;
    }
}

static inline gnrc_netif_t *gnrc_netif_hdr_get_netif(const gnrc_netif_hdr_t *hdr) /* <=== gnrc_netif_hdr_get_netif */ 
{
    assert(hdr != NULL);
    return gnrc_netif_get_by_pid(hdr->if_pid);
}

static inline void clist_rpush(clist_node_t *list, clist_node_t *new_node) /* <=== clist_rpush */ 
{
    if (list->next) {
        new_node->next = list->next->next;
        list->next->next = new_node;
    }
    else {
        new_node->next = new_node;
    }
    list->next = new_node;
}

static inline uint8_t *gnrc_netif_hdr_get_src_addr(const gnrc_netif_hdr_t *hdr) /* <=== gnrc_netif_hdr_get_src_addr */ 
{
    return ((uint8_t *)(hdr + 1));
}

